"use client";

/**
 * Ring meter: a progress ring sweeps round to a percentage while the number
 * counts in its centre, then a caption settles under it. One clean share of
 * a whole.
 *
 * Written by Better Design. Painted from the theme prop, so the sweep takes
 * the product's primary colour and the track takes a quiet tint of its ink.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

const SWEEP_AT = 8;
const SWEEP_FRAMES = 56;
const CAPTION_AT = 52;

const SIZE = 560;
const STROKE = 36;

export interface RingMeterProps {
  /** The share the ring sweeps to, from 0 to 100. */
  value?: number;
  /** One line under the ring that says what the share is of. */
  caption?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** Sweep a ring to a percentage with the figure counting in its centre. */
export function RingMeter({
  value = 72,
  caption = "of the plan is complete",
  theme: themeOverride,
  font,
}: RingMeterProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const target = Math.min(100, Math.max(0, value));
  const enter = easings.out(interpolate(frame, [0, 16], [0, 1], clamp));
  const sweep = easings.inOut(interpolate(frame, [SWEEP_AT, SWEEP_AT + SWEEP_FRAMES], [0, 1], clamp));
  const shown = Math.round(target * sweep);
  const captionT = easings.out(interpolate(frame, [CAPTION_AT, CAPTION_AT + 18], [0, 1], clamp));

  const r = (SIZE - STROKE) / 2;
  const circumference = 2 * Math.PI * r;
  const dash = circumference * (target / 100) * sweep;

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 56 }}>
        <div style={{ position: "relative", width: SIZE, height: SIZE, opacity: enter, transform: `scale(${0.94 + 0.06 * enter})` }}>
          <svg width={SIZE} height={SIZE} style={{ transform: "rotate(-90deg)" }}>
            <circle cx={SIZE / 2} cy={SIZE / 2} r={r} fill="none" stroke={withAlpha(theme.foreground, 0.08)} strokeWidth={STROKE} />
            <circle
              cx={SIZE / 2}
              cy={SIZE / 2}
              r={r}
              fill="none"
              stroke={theme.primary}
              strokeWidth={STROKE}
              strokeLinecap="round"
              strokeDasharray={`${dash} ${circumference}`}
              opacity={sweep > 0.002 ? 1 : 0}
            />
          </svg>
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: theme.foreground,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            <span style={{ fontSize: 176, fontWeight: 700, letterSpacing: "-0.05em", lineHeight: 1 }}>{shown}</span>
            <span style={{ fontSize: 72, fontWeight: 500, color: theme.mutedForeground, marginLeft: 6, alignSelf: "flex-start", marginTop: 196 }}>%</span>
          </div>
        </div>
        <div style={{ fontSize: 44, fontWeight: 500, color: theme.mutedForeground, opacity: captionT, transform: `translateY(${(1 - captionT) * 14}px)` }}>
          {caption}
        </div>
      </div>
    </AbsoluteFill>
  );
}
